   122→
   123→				<!-- AC: @web-dashboard ac-12, ac-15 - Acceptance Criteria (GWT format) -->
   124→				{#if item.acceptance_criteria && item.acceptance_criteria.length > 0}
   125→					<div data-testid="acceptance-criteria">
   126→						<h3 class="text-sm font-semibold mb-2">Acceptance Criteria</h3>
   127→						<Accordion type="multiple" class="w-full">
   128→							{#each item.acceptance_criteria as ac, i}
   129→								<AccordionItem value={ac._ulid} data-testid="ac-item">
   130→									<AccordionTrigger data-testid="ac-expand-toggle">
   131→										<span class="text-sm" data-testid="ac-given">AC-{i + 1}: {ac.given}</span>
   132→									</AccordionTrigger>
   133→									<AccordionContent>
   134→										<div class="space-y-2 text-sm pl-4">
   135→											<div data-testid="ac-given-full">
   136→												<span class="font-medium text-muted-foreground">Given:</span>
   137→												{ac.given}
   138→											</div>
   139→											<div data-testid="ac-when-full">
   140→												<span class="font-medium text-muted-foreground">When:</span>
   141→												{ac.when}
   142→											</div>
   143→											<div data-testid="ac-then-full">
   144→												<span class="font-medium text-muted-foreground">Then:</span>
   145→												{ac.then}
   146→											</div>
   147→											<!-- AC: @web-dashboard ac-15 - Test coverage indicator -->
   148→											<div
   149→												data-testid="test-coverage-indicator"
   150→												class="text-xs mt-2 inline-flex items-center gap-1 {ac.covered === true
   151→													? 'text-green-600 covered'
   152→													: ac.covered === false
   153→														? 'text-amber-600 uncovered'
   154→														: 'text-muted-foreground unknown'}"
   155→											>
   156→												{#if ac.covered === true}
   157→													<CheckCircle class="w-3 h-3" />
   158→													<span>Covered</span>
   159→												{:else if ac.covered === false}
   160→													<XCircle class="w-3 h-3" />
   161→													<span>Not covered</span>
   162→												{:else}
   163→													<HelpCircle class="w-3 h-3" />
   164→													<span>Coverage: Unknown</span>
   165→												{/if}
