   182→									variant="outline"
   183→									size="sm"
   184→									data-testid="trait-chip"
   185→									onclick={() => {
   186→										// AC: @web-dashboard ac-14 - Navigate to trait detail
   187→										// Traits are items (type: trait), so we navigate to items view with the ref
   188→										const traitRef = trait.startsWith('@') ? trait.slice(1) : trait;
   189→										goto(`${base}/items?ref=${encodeURIComponent(traitRef)}`);
   190→									}}
   191→								>
   192→									<span data-testid="trait-title">{trait}</span>
