   206→									href="{base}/tasks?ref={encodeURIComponent(task._ulid)}"
   207→									class="flex items-center gap-2 p-2 rounded border hover:bg-muted/50 transition-colors"
   208→									data-testid="linked-task"
   209→								>
   210→									<Badge class={getStatusColor(task.status)} data-testid="task-status-badge"
   211→										>{formatStatus(task.status)}</Badge
   212→									>
   213→									<span class="text-sm flex-1" data-testid="task-title">{task.title}</span>
   214→									{#if task.notes_count > 0}
   215→										<Badge variant="secondary" class="text-xs">{task.notes_count} notes</Badge>
   216→									{/if}
   217→								</a>
   218→							{/each}
   219→						</div>
   220→					</div>
   221→				{:else}
   222→					<div data-testid="implementation-section">
   223→						<h3 class="text-sm font-semibold mb-2">Implementation</h3>
   224→						<p class="text-sm text-muted-foreground">No tasks linked to this spec item yet.</p>
   225→					</div>
   226→				{/if}
   227→			</div>
   228→		{/if}
   229→	</SheetContent>
   230→</Sheet>
